import {Ajv} from 'ajv';
import type {ErrorObject, ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
}

function describeSchemaError(error: ErrorObject): string {
  const path = error.instancePath || '/';
  switch (error.keyword) {
    case 'required':
      return `${error.params.missingProperty} is required`;
    case 'type':
      return `${path} must be of type ${error.params.type}`;
    default:
      return `${path} ${error.message ?? 'is invalid'}`;
  }
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : String(error);
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${reason}`);
    }
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (tool.validator) return tool.validator;
    const definition = this.resolveDefinition(tool.definitionSource);
    let validator = this.dynamicValidators.get(definition.inputSchema);
    if (!validator) {
      validator = this.compile(definition);
      this.dynamicValidators.set(definition.inputSchema, validator);
    }
    return validator;
  }

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, validator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Rejects schema-invalid input as a ToolResponse; throws only for an unknown tool (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validator = this.validatorFor(tool);
    if (!validator(input)) {
      const problems = (validator.errors ?? []).map(describeSchemaError);
      log.warn('tool', 'input rejected', {name, problems});
      return {result: `Invalid input for tool ${name}: ${problems.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('rejects input missing a required property without calling the executor', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    const executor = async () => {
      executorCalls += 1;
      return 'sunny';
    };
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {type: 'object', properties: {location: {type: 'string'}}, required: ['location']},
      },
      executor
    );

    const response = await registry.execute('get_weather', {});

    expect(response.result).toMatch(/location/);
    expect(response.result).toMatch(/required/i);
    expect(executorCalls).toBe(0);
  });
});
# Changelog

All notable changes to `@re-cinq/hal-engine` are documented here.

The format is [Keep a Changelog 1.1.0](https://keepachangelog.com/en/1.1.0/), and this project adheres to
[Semantic Versioning](https://semver.org/spec/v2.0.0.html). Entries are written for somebody installing the
package, not for somebody reading this repository's commit log.

## [Unreleased]

## [0.3.0] - 2026-09-17

### Changed

- `HalEngineConfig.orchestrator.hooks` now carries a JSDoc comment. The field already shipped
  in `0.2.x`; the comment makes the lifecycle-hook seam discoverable from the published type
  declarations so editors surface it on hover without a trip to the README.

## [0.2.1] - 2026-09-14

Identical to `0.2.0` — same files, same code. It exists to prove that a release publishes with no
credential stored in the repository: `0.2.0` had to be published with a token, because the registry
cannot hold a trusted publisher for a name that has never been published, and this is the first version
released through that publisher instead. There is nothing here to upgrade for.

## [0.2.0] - 2026-09-14

The first release under the `@re-cinq` scope. Nothing has been published before it, so there is no upgrade
path from `0.1.0` on the registry — only from the git specifier.

#!/usr/bin/env bash
# Fails when a diff touches src/ and leaves CHANGELOG.md alone.
#
# Usage:
#   bash scripts/check-changelog.sh [base-ref]     # default: origin/main
#
# The rule is about what a consumer can observe, not about effort: anything that
# changes shipped behaviour needs a sentence they can read on npm. A change to
# src/ that genuinely is not user-visible - an internal refactor, a test-only
# edit - takes the `no-changelog` label instead, which is a deliberate, visible
# act rather than a silent omission.
set -uo pipefail

base="${1:-origin/main}"

# A base ref that does not resolve means nothing was compared. On a laptop that
# is ordinary - a fresh clone has no origin/main - and skipping is right. In CI
# it is the gate passing without running, which is the one outcome a gate must
# never have, and it is exactly how a fetch that failed went unnoticed.
if ! git rev-parse --verify --quiet "$base" >/dev/null; then
  if [ -n "${GITHUB_ACTIONS:-}" ]; then
    echo "check-changelog: FAILED - base ref '$base' does not resolve, so nothing was checked" >&2
    exit 1
  fi
  echo "check-changelog: base ref '$base' not found; skipping" >&2
  exit 0
fi

merge_base="$(git merge-base "$base" HEAD)"
changed="$(git diff --name-only "$merge_base"..HEAD)"
